{
    id: "43FEC71E36DEB59A"
    title: "Открыть сокровищницу кузницы"
    x: 0d
    y: 0d
    icon: "minecraft:blaze_powder"
    shape: "shield"
    size: 1.5d
    optional: true
    dependencies: ["FC2F522F0B5765F9"]
    description: ["Победите ифрита внутри древней кузницы и откройте ещё не тронутый сундук её сокровищницы. Это два отдельных результата похода; проверяйте обе цели в карточке.", "Подготовьте огнестойкость, щит и обратный путь. Во время решающего удара и вы, и ифрит должны находиться внутри кузницы. За сокровищами осматривайте развилки коридоров; сундуки обычных проходов и лавовых ям не подходят.", "Приз — четыре пламенных пирожных Create. Они дают горелке с ифритом сверхнагрев для особых рецептов: это повод вернуться в мастерскую с новым опытом. Для обычного нагрева такой дорогой запас лучше поберечь.", "Сокровищница, открытая до появления этого задания, повторно не засчитается: понадобится нетронутый сундук нужного вида, возможно в другой кузнице."]
    tasks: [
        {"id": "43BCF460A121D592", "type": "advancement", "advancement": "nasledie:alpha43/expeditions/foundry_blaze", "title": "Победить ифрита внутри кузницы"}
        {"id": "4375F52DFFB15A8B", "type": "advancement", "advancement": "nasledie:alpha43/expeditions/foundry_treasure", "title": "Впервые открыть сокровищницу кузницы"}
    ]
    rewards: [
        { id: "4319053824753868" type: "xp" xp: 350 }
        { id: "4326325C2C79DDB7" type: "item" item: { id: "create:blaze_cake" Count: 4b } }
    ]
}

{
    id: "437A23B0113CA26B"
    title: "Открыть сокровищницу гнезда"
