}

{
    id: "43B6739A38C338FD"
    title: "Открыть сокровищницу храма"
    x: 0d
    y: 0d
    icon: "minecraft:fermented_spider_eye"
    shape: "shield"
    size: 1.5d
    optional: true
    dependencies: ["1B7D417FC2AD346C"]
    description: ["Победите пещерного паука внутри заражённого храма и доберитесь до ещё не открытого сокровищного сундука в верхней внутренней части сооружения.", "Возьмите средство против яда, еду и блоки для безопасного отхода. В решающий момент и вы, и паук должны находиться внутри храма; обычный паук не заменяет пещерного.", "Две цели завершают поход, начатый поиском монастырской карты. Сундуки библиотеки, сада, кузницы и складов не считаются верхней сокровищницей. Уже открытый до появления задания сундук повторно не засчитается.", "Зачарованное золотое яблоко — редкий запас для следующей опасной экспедиции."]
    tasks: [
        {"id": "43E15D9CC3647A36", "type": "advancement", "advancement": "nasledie:alpha43/expeditions/temple_cave_spider", "title": "Победить пещерного паука в храме"}
        {"id": "438C7870B2463450", "type": "advancement", "advancement": "nasledie:alpha43/expeditions/temple_treasure", "title": "Впервые открыть верхнюю сокровищницу"}
    ]
    rewards: [
        { id: "43DB952F3AFEDD7C" type: "xp" xp: 350 }
        { id: "4317CEE35620CB12" type: "item" item: { id: "minecraft:enchanted_golden_apple" Count: 1b } }
