nasledie_industry.snbt:
{
    id: "43927DB0D42A5F58"
    title: "Проволока от электропривода"
    x: 0d
    y: 0d
    icon: "createaddition:copper_wire"
    shape: "star"
    size: 1.5d
    optional: true
    dependencies: ["C90C2277CD8D5A1A"]
    description: ["Запустите прокатный стан от электродвигателя и превратите один медный лист Create в две медные проволоки. Теперь ваша электрическая линия делает материал для собственного расширения: из проволоки собираются катушки для новых соединений.", "Подведите электричество к двигателю через разъём и катушку, затем соедините его вращающийся выход со станом напрямую или валами и шестернями. Генератору нужен отдельный механический привод; накопитель позволяет использовать запас заряда. Замкнутый круг «двигатель → генератор → тот же двигатель» не создаёт энергию.", "Медный лист получается из медного слитка под прессом. В стане слиток даст стержни, а для этой цели нужна именно проволока из листа. При необходимости смотрите рецепт предмета и встроенные сцены с устройством станков.", "Для зачёта сделайте контрольный выпуск: освободите выход стана, временно отключите автоматическую подачу и выгрузку. Возьмите обычные часы в основную руку и нажмите ими правой кнопкой по вращающемуся стану. Затем в течение минуты положите на вход ровно один медный лист; часы можно убрать, чтобы открыть стан.", "Дождитесь сообщения об успешном выпуске, прежде чем забирать проволоку. Оставайтесь не дальше 16 блоков; для опыта используйте короткий привод до 32 звеньев. Максим может наблюдать, а Юра — подавать лист. После выхода из игры незаконченный опыт нужно начать часами заново.", "Четыре латунные воронки из награды помогут превратить контрольный стан в постоянную линию: настройте подачу листов и выдачу проволоки, затем добавляйте новые рабочие места по мере необходимости."]
    tasks: [
        {"id": "43DA5FE12471C262", "type": "advancement", "advancement": "nasledie:alpha43/industry/electric_wire", "title": "Прокатать медный лист на электроприводе"}
    ]
    rewards: [
        { id: "43609D0BB3655592" type: "xp" xp: 300 }
        { id: "43830694594B33E9" type: "item" item: { id: "create:brass_funnel" Count: 4b } }
    ]
}

{
    id: "43CE9DDCB2EF166C"
    title: "Походная мельница на дизеле"
    x: 0d
    y: 0d
    icon: "create:wheat_flour"
    shape: "star"
    size: 1.5d
    optional: true
    dependencies: ["01A997FB916A7F84"]
    description: ["Запустите жернова Create от обычного дизельного двигателя и смелите одну пшеницу в муку. Такой компактный привод пригодится для мастерской у дальней базы: вы сами выбираете место и привозите запас топлива.", "Залейте дизель в бак двигателя и передайте вращение жерновам напрямую или валами и шестернями. Проверьте, что источник действительно работает и нагрузка не остановила линию. В этом опыте используется обычный одноблочный двигатель и именно дизельное топливо.", "Для зачёта освободите выход жерновов и временно отключите автоматическую подачу и выгрузку. Возьмите обычные часы в основную руку и нажмите ими правой кнопкой по вращающимся жерновам. Затем в течение минуты подайте ровно одну пшеницу; часы можно убрать, чтобы открыть жернова.", "Дождитесь сообщения об успешном помоле, прежде чем забирать муку. Оставайтесь не дальше 16 блоков и используйте короткий привод до 32 звеньев. Иногда жернова дают дополнительную муку или семена — такой результат тоже подходит. После выхода из игры незаконченный опыт нужно начать часами заново.", "Дальше превращайте муку в тесто и хлеб знакомым способом из главы Create, верните автоматическую подачу и готовьте припасы для новых вылазок. Восемь порций мяса с картофелем из награды накормят вас, пока вы обустраиваете производство."]
    tasks: [
        {"id": "43D5DC583A7E887D", "type": "advancement", "advancement": "nasledie:alpha43/industry/diesel_flour", "title": "Смолоть пшеницу от дизельного двигателя"}
    ]
    rewards: [
        { id: "43A69B423A4DE45F" type: "xp" xp: 300 }
        { id: "430ACBBAEF2DDB2B" type: "item" item: { id: "farmersdelight:steak_and_potatoes" Count: 8b } }
    ]
}
